import { siteConfig } from "@/content/site";

export type ContributionDay = {
  date: string;
  count: number;
  level: 0 | 1 | 2 | 3 | 4;
};

export type GitHubContributionResult = {
  available: boolean;
  username: string;
  profileUrl: string;
  totalContributions?: number;
  weeks?: (ContributionDay | null)[][];
  reason?: string;
};

/**
 * Fetches verified public contribution calendar directly from the user's GitHub profile.
 * Parses the exact (col, row) coordinates generated by GitHub's DOM (row 0=Sunday to 6=Saturday).
 */
async function fetchPublicContributions(
  username: string
): Promise<{ totalContributions: number; weeks: (ContributionDay | null)[][] } | null> {
  try {
    const response = await fetch(
      `https://github.com/users/${encodeURIComponent(username)}/contributions`,
      {
        headers: {
          "User-Agent":
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        },
        next: { revalidate: 3600 },
      }
    );

    if (!response.ok) {
      return null;
    }

    const html = await response.text();

    const totalMatch = html.match(
      /([0-9,]+)\s+contributions\s+in the last year/i
    );
    const total = totalMatch
      ? parseInt(totalMatch[1].replace(/,/g, ""), 10)
      : 0;

    const tooltips = new Map<string, number>();
    const tooltipRegex =
      /<tool-tip[^>]+for="([^"]+)"[^>]*>([^<]+)<\/tool-tip>/gi;
    let tMatch: RegExpExecArray | null;
    while ((tMatch = tooltipRegex.exec(html)) !== null) {
      const text = tMatch[2].trim();
      const countMatch = text.match(/^(\d+)\s+contribution/i);
      const count = countMatch ? parseInt(countMatch[1], 10) : 0;
      tooltips.set(tMatch[1], count);
    }

    // Fixed 53 weeks x 7 weekdays matrix initialized to null
    const matrix: (ContributionDay | null)[][] = Array.from({ length: 53 }, () =>
      Array(7).fill(null)
    );

    const tdRegex =
      /<td\s+([^>]*class="[^"]*ContributionCalendar-day[^"]*"[^>]*)>/gi;
    let tdMatch: RegExpExecArray | null;
    let matchedCells = 0;

    while ((tdMatch = tdRegex.exec(html)) !== null) {
      const attrs = tdMatch[1];
      const idMatch = attrs.match(/id="contribution-day-component-(\d+)-(\d+)"/);
      if (!idMatch) continue;

      const row = parseInt(idMatch[1], 10);
      const col = parseInt(idMatch[2], 10);
      if (row < 0 || row > 6 || col < 0 || col >= 53) continue;

      const dateMatch = attrs.match(/data-date="([^"]+)"/);
      const levelMatch = attrs.match(/data-level="([^"]+)"/);
      if (!dateMatch) continue;

      const date = dateMatch[1];
      const rawLevel = levelMatch ? parseInt(levelMatch[1], 10) : 0;
      const level: 0 | 1 | 2 | 3 | 4 =
        rawLevel >= 0 && rawLevel <= 4 ? (rawLevel as 0 | 1 | 2 | 3 | 4) : 0;
      const id = `contribution-day-component-${row}-${col}`;
      const tipCount = tooltips.get(id);

      matrix[col][row] = {
        date,
        level,
        count: tipCount !== undefined ? tipCount : level > 0 ? 1 : 0,
      };
      matchedCells++;
    }

    if (matchedCells === 0) {
      return null;
    }

    let calculatedTotal = 0;
    for (let c = 0; c < 53; c++) {
      for (let r = 0; r < 7; r++) {
        const cell = matrix[c][r];
        if (cell) {
          calculatedTotal += cell.count;
        }
      }
    }

    return {
      totalContributions: total > 0 ? total : calculatedTotal,
      weeks: matrix,
    };
  } catch {
    return null;
  }
}

/**
 * Fetches GitHub contribution data on the server.
 * Prioritizes GitHub GraphQL API when GITHUB_TOKEN is configured (which accesses private activity),
 * otherwise fetches verified public activity directly from GitHub.
 */
export async function getGitHubContributions(): Promise<GitHubContributionResult> {
  const username = siteConfig.githubUsername;
  const profileUrl = siteConfig.githubUrl;
  const token = process.env.GITHUB_TOKEN?.trim();

  // If a GITHUB_TOKEN is available, query the official GraphQL endpoint
  if (token) {
    try {
      const query = `
        query($username: String!) {
          user(login: $username) {
            contributionsCollection {
              contributionCalendar {
                totalContributions
                weeks {
                  contributionDays {
                    date
                    contributionCount
                    contributionLevel
                    weekday
                  }
                }
              }
            }
          }
        }
      `;

      const response = await fetch("https://api.github.com/graphql", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
          "User-Agent": "portfolio-app",
        },
        body: JSON.stringify({ query, variables: { username } }),
        next: { revalidate: 3600 },
      });

      if (response.ok) {
        const json = await response.json();
        const calendar =
          json?.data?.user?.contributionsCollection?.contributionCalendar;

        if (calendar) {
          const levelMap: Record<string, 0 | 1 | 2 | 3 | 4> = {
            NONE: 0,
            FIRST_QUARTILE: 1,
            SECOND_QUARTILE: 2,
            THIRD_QUARTILE: 3,
            FOURTH_QUARTILE: 4,
          };

          const matrix: (ContributionDay | null)[][] = Array.from(
            { length: calendar.weeks.length },
            () => Array(7).fill(null)
          );

          calendar.weeks.forEach(
            (
              week: {
                contributionDays: {
                  date: string;
                  contributionCount: number;
                  contributionLevel: string;
                  weekday?: number;
                }[];
              },
              colIdx: number
            ) => {
              week.contributionDays.forEach((day) => {
                const row =
                  typeof day.weekday === "number"
                    ? day.weekday
                    : new Date(`${day.date}T00:00:00Z`).getUTCDay();

                matrix[colIdx][row] = {
                  date: day.date,
                  count: day.contributionCount,
                  level: levelMap[day.contributionLevel] ?? 0,
                };
              });
            }
          );

          return {
            available: true,
            username,
            profileUrl,
            totalContributions: calendar.totalContributions,
            weeks: matrix,
          };
        }
      }
    } catch {
      // Fallback to public contribution fetcher
    }
  }

  // Fetch verified public contribution data directly from GitHub
  const publicData = await fetchPublicContributions(username);
  if (publicData) {
    return {
      available: true,
      username,
      profileUrl,
      totalContributions: publicData.totalContributions,
      weeks: publicData.weeks,
    };
  }

  return {
    available: false,
    username,
    profileUrl,
    reason: "Unable to retrieve GitHub activity at this time.",
  };
}
